#include "s61_binary_deeper_cubic_field_20261101.hpp"
#include <chrono>
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
using Mat=vector<vector<Poly>>;
Mat readmat(istream&in,int nr,int nc){int n,m;in>>n>>m;assert(n==nr&&m==nc);Mat A(n,vector<Poly>(m));for(auto&r:A)for(auto&p:r)read_poly(in,p.p);return A;}
int main(int argc,char**argv){assert(argc==5);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),ein(argv[2]);ofstream out(argv[3]),co(argv[4]);assert(in&&ein&&out&&co);Poly D1,D2,DQ;read_poly(in,D1.p);read_poly(in,D2.p);read_poly(in,DQ.p);vector<int>qp(132);for(int&i:qp)in>>i;vector<map<int,string>>B(238);for(auto&r:B){int n;in>>n;for(int k=0;k<n;k++){int j;string c;in>>j>>c;r[j]=c;}}Mat A1=readmat(in,189,238),A2=readmat(in,189,106);int n,m;ein>>n>>m;assert(n==117&&m==189);Mat E(117,vector<Poly>(189));for(auto&r:E){Poly den,g;read_poly(ein,den.p);read_poly(ein,g.p);for(auto&p:r)read_poly(ein,p.p);}out<<117<<' '<<238<<' '<<106<<'\n';co<<117<<' '<<106<<'\n';auto start=chrono::steady_clock::now();long total=0;fmpq_t coef;fmpq_init(coef);for(int i=0;i<117;i++){vector<Poly>first(238),second(106),cfree(106);Poly tmp;for(int h=0;h<189;h++)if(!fmpq_mpoly_is_zero(E[i][h].p,ctx)){for(int j=0;j<238;j++)if(!fmpq_mpoly_is_zero(A1[h][j].p,ctx)){fmpq_mpoly_mul(tmp.p,E[i][h].p,A1[h][j].p,ctx);fmpq_mpoly_add(first[j].p,first[j].p,tmp.p,ctx);}for(int j=0;j<106;j++)if(!fmpq_mpoly_is_zero(A2[h][j].p,ctx)){fmpq_mpoly_mul(tmp.p,E[i][h].p,A2[h][j].p,ctx);fmpq_mpoly_add(second[j].p,second[j].p,tmp.p,ctx);}}for(int j=0;j<238;j++)if(!fmpq_mpoly_is_zero(first[j].p,ctx))for(auto&[h,c]:B[j]){assert(fmpq_set_str(coef,c.c_str(),10)==0);fmpq_canonicalise(coef);fmpq_mpoly_scalar_mul_fmpq(tmp.p,first[j].p,coef,ctx);fmpq_mpoly_add(cfree[h].p,cfree[h].p,tmp.p,ctx);}for(auto&v:first){write(out,v);total+=fmpq_mpoly_length(v.p,ctx);}for(auto&v:second){write(out,v);total+=fmpq_mpoly_length(v.p,ctx);}for(auto&v:cfree)write(co,v);out.flush();co.flush();double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(i%10==0)cerr<<"DUAL_BLOCK "<<i<<" TERMS "<<total<<" SEC "<<sec<<'\n';assert(total<8000000);}fmpq_clear(coef);cerr<<"PASS "<<total<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
